@push('scripts')<script>document.querySelector('form.card').addEventListener('submit',function(){const f=this;[['bullets_text','bullet_points'],['image_urls_text','image_urls']].forEach(([source,target])=>{const input=document.createElement('input');input.type='hidden';input.name=target+'[]';input.value='';f.appendChild(input);const vals=(f.elements[source].value||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);f.querySelectorAll('input[name="'+target+'[]"]').forEach(e=>e.remove());vals.forEach(v=>{const x=document.createElement('input');x.type='hidden';x.name=target+'[]';x.value=v;f.appendChild(x);});f.elements[source].disabled=true;});});</script>@endpush
